pub struct P<'a> {
    s: &'a [u8],
    i: usize,
}

impl<'a> P<'a> {
    pub fn new(s: &'a str) -> Self {
        P { s: s.as_bytes(), i: 0 }
    }

    fn peek(&self) -> Option<u8> {
        self.s.get(self.i).copied()
    }

    fn eat(&mut self, c: u8) -> bool {
        while self.peek().is_some_and(|b| b.is_ascii_whitespace()) {
            self.i += 1;
        }
        if self.peek() == Some(c) {
            self.i += 1;
            return true;
        }
        false
    }

    // A quoted string (with escapes) or a bare token up to , or ].
    fn token(&mut self) -> String {
        let mut o = Vec::new();
        if self.eat(b'"') {
            while let Some(c) = self.peek().filter(|&c| c != b'"') {
                self.i += 1;
                if c == b'\\' && self.i < self.s.len() {
                    o.push(match self.s[self.i] {
                        b'n' => b'\n',
                        b't' => b'\t',
                        c => c,
                    });
                    self.i += 1;
                } else {
                    o.push(c);
                }
            }
            self.i += 1; // closing quote
            return String::from_utf8_lossy(&o).into_owned();
        }
        while let Some(c) = self.peek().filter(|&c| c != b',' && c != b']') {
            o.push(c);
            self.i += 1;
        }
        String::from_utf8_lossy(&o).trim_end().to_string()
    }
}

// Reading and printing in LeetCode's own testcase format.
pub trait Leet: Sized {
    fn parse(p: &mut P) -> Self;
    fn show(&self, out: &mut String);
}

macro_rules! number {
    ($($t:ty)*) => {$(
        impl Leet for $t {
            fn parse(p: &mut P) -> Self {
                let t = p.token();
                if t.is_empty() {
                    return Self::default();
                }
                t.parse().unwrap_or_else(|_| panic!("leetgen: cannot read {t:?} as {}", stringify!($t)))
            }
            fn show(&self, out: &mut String) {
                out.push_str(&self.to_string());
            }
        }
    )*};
}
number!(i32 i64 u32 u64 usize f64);

impl Leet for bool {
    fn parse(p: &mut P) -> Self {
        p.token() == "true"
    }
    fn show(&self, out: &mut String) {
        out.push_str(if *self { "true" } else { "false" });
    }
}

impl Leet for String {
    fn parse(p: &mut P) -> Self {
        p.token()
    }
    fn show(&self, out: &mut String) {
        out.push('"');
        for c in self.chars() {
            if c == '"' || c == '\\' {
                out.push('\\');
            }
            out.push(c);
        }
        out.push('"');
    }
}

impl Leet for char {
    fn parse(p: &mut P) -> Self {
        p.token().chars().next().unwrap_or('\0')
    }
    fn show(&self, out: &mut String) {
        out.push('"');
        out.push(*self);
        out.push('"');
    }
}

// A method without a return value: `null` in a design problem's results.
impl Leet for () {
    fn parse(_: &mut P) -> Self {}
    fn show(&self, out: &mut String) {
        out.push_str("null");
    }
}

impl<T: Leet> Leet for Vec<T> {
    fn parse(p: &mut P) -> Self {
        let mut v = Vec::new();
        if !p.eat(b'[') || p.eat(b']') {
            return v;
        }
        loop {
            v.push(T::parse(p));
            if !p.eat(b',') {
                break;
            }
        }
        p.eat(b']');
        v
    }
    fn show(&self, out: &mut String) {
        out.push('[');
        for (i, x) in self.iter().enumerate() {
            if i > 0 {
                out.push(',');
            }
            x.show(out);
        }
        out.push(']');
    }
}

impl Leet for Option<Box<ListNode>> {
    fn parse(p: &mut P) -> Self {
        let mut head = None;
        for val in Vec::<i32>::parse(p).into_iter().rev() {
            head = Some(Box::new(ListNode { val, next: head }));
        }
        head
    }
    fn show(&self, out: &mut String) {
        let mut vals = Vec::new();
        let mut cur = self;
        while let Some(node) = cur {
            vals.push(node.val);
            cur = &node.next;
        }
        vals.show(out);
    }
}

// Level order with `null` holes, trailing holes trimmed.
impl Leet for Option<Rc<RefCell<TreeNode>>> {
    fn parse(p: &mut P) -> Self {
        let mut vals = Vec::<String>::parse(p).into_iter().map(|t| {
            (t != "null" && !t.is_empty())
                .then(|| t.parse::<i32>().unwrap_or_else(|_| panic!("leetgen: cannot read {t:?} as a tree value")))
        });
        let root = Rc::new(RefCell::new(TreeNode::new(vals.next()??)));
        let mut queue = VecDeque::from([Rc::clone(&root)]);
        while let Some(node) = queue.pop_front() {
            for left in [true, false] {
                let Some(slot) = vals.next() else {
                    return Some(root);
                };
                let child = slot.map(|val| Rc::new(RefCell::new(TreeNode::new(val))));
                queue.extend(child.clone());
                let mut node = node.borrow_mut();
                *(if left { &mut node.left } else { &mut node.right }) = child;
            }
        }
        Some(root)
    }
    fn show(&self, out: &mut String) {
        let mut vals = Vec::new();
        let mut queue = VecDeque::from([self.clone()]);
        while let Some(slot) = queue.pop_front() {
            vals.push(slot.as_ref().map(|node| node.borrow().val.to_string()));
            if let Some(node) = slot {
                queue.push_back(node.borrow().left.clone());
                queue.push_back(node.borrow().right.clone());
            }
        }
        while vals.last() == Some(&None) {
            vals.pop();
        }
        let vals: Vec<String> = vals.into_iter().map(|v| v.unwrap_or_else(|| "null".into())).collect();
        out.push('[');
        out.push_str(&vals.join(","));
        out.push(']');
    }
}

// One raw input line. LeetCode gives one argument per line.
pub fn line() -> String {
    let mut l = String::new();
    std::io::stdin().lock().read_line(&mut l).expect("leetgen: cannot read stdin");
    l.trim_end_matches(['\n', '\r']).to_string()
}

pub fn read<T: Leet>() -> T {
    T::parse(&mut P::new(&line()))
}

// Top-level elements of a bracketed list as raw text, nested brackets kept:
// the per-call argument groups of a design problem.
pub fn groups(line: &str) -> Vec<String> {
    let (Some(a), Some(b)) = (line.find('['), line.rfind(']')) else {
        return Vec::new();
    };
    let mut out = Vec::new();
    if b <= a {
        return out;
    }
    let (mut depth, mut quoted, mut prev, mut cur) = (0, false, '\0', String::new());
    for c in line[a + 1..b].chars() {
        if c == '"' && prev != '\\' {
            quoted = !quoted;
        }
        prev = c;
        if !quoted {
            match c {
                '[' => depth += 1,
                ']' => depth -= 1,
                ',' if depth == 0 => {
                    out.push(cur.trim().to_string());
                    cur.clear();
                    continue;
                }
                _ => {}
            }
        }
        cur.push(c);
    }
    if !cur.trim().is_empty() {
        out.push(cur.trim().to_string());
    }
    out
}

// One argument out of a design problem's group, by index.
pub fn arg<T: Leet>(parts: &[String], i: usize) -> T {
    T::parse(&mut P::new(parts.get(i).map_or("", String::as_str)))
}

pub fn ser<T: Leet>(v: &T) -> String {
    let mut s = String::new();
    v.show(&mut s);
    s
}

pub fn print<T: Leet>(v: &T) {
    println!("{}", ser(v));
}
